package com.weeklyplan.partner;
import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/partner-resources") public class PartnerResourceController { private final PartnerResourceService resources; public PartnerResourceController(PartnerResourceService r){resources=r;} @GetMapping public List<PartnerResourceResponse> list(){return resources.list();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public PartnerResourceResponse create(@Valid @RequestBody SavePartnerResourceRequest r){return resources.create(r);} @PutMapping("/{id}") public PartnerResourceResponse update(@PathVariable Long id,@Valid @RequestBody SavePartnerResourceRequest r){return resources.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){resources.delete(id);} @GetMapping("/{id}/contacts") public List<PartnerResourceContactResponse> contacts(@PathVariable Long id){return resources.contacts(id);}@PostMapping("/{id}/contacts") @ResponseStatus(HttpStatus.CREATED) public PartnerResourceContactResponse addContact(@PathVariable Long id,@Valid @RequestBody SavePartnerContactRequest r){return resources.addContact(id,r);}@DeleteMapping("/{resourceId}/contacts/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteContact(@PathVariable Long resourceId,@PathVariable Long id){resources.deleteContact(resourceId,id);}@GetMapping("/{id}/follow-ups") public List<PartnerResourceFollowUpResponse> followUps(@PathVariable Long id){return resources.followUps(id);}@PostMapping("/{id}/follow-ups") @ResponseStatus(HttpStatus.CREATED) public PartnerResourceFollowUpResponse addFollowUp(@PathVariable Long id,@Valid @RequestBody SavePartnerFollowUpRequest r){return resources.addFollowUp(id,r);}@DeleteMapping("/{resourceId}/follow-ups/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteFollowUp(@PathVariable Long resourceId,@PathVariable Long id){resources.deleteFollowUp(resourceId,id);}@GetMapping("/{id}/projects") public List<PartnerResourceProjectResponse> projects(@PathVariable Long id){return resources.projects(id);}@PostMapping("/{id}/projects") @ResponseStatus(HttpStatus.CREATED) public PartnerResourceProjectResponse linkProject(@PathVariable Long id,@Valid @RequestBody SavePartnerProjectRequest r){return resources.linkProject(id,r);}@DeleteMapping("/{resourceId}/projects/{projectId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void unlinkProject(@PathVariable Long resourceId,@PathVariable Long projectId){resources.unlinkProject(resourceId,projectId);} }
